    def _protocol_feature(bits: bytes, feature: int) -> bool:
        index, offset = divmod(feature, 8)
        return index < len(bits) and bool(bits[index] & (1 << (7 - offset)))


    class SqliProtocolError(RuntimeError):
        pass


    @dataclass(frozen=True)
    class InformixDatetimeLiteral:
        """A canonical partial DATETIME value paired with its native qualifier."""

        value: str
        qualifier: int


    class SqliTransportError(SqliProtocolError):
        """A connection-specific SQLI failure that is safe to retry on another address."""


    class SqliSessionRejected(SqliProtocolError):
        """Informix rejected the SQLI session before authentication diagnostics."""


    def informix_locale_encoding(locale: str | None) -> str:
        """Return the verified Python codec for an Informix locale codeset."""

        codeset = (locale or "en_US.utf8").rsplit(".", 1)[-1].lower()
        aliases = {
            "819": "iso8859-1",
            "iso8859-1": "iso8859-1",
            "iso-8859-1": "iso8859-1",
            "utf8": "utf-8",
            "utf-8": "utf-8",
            "57372": "utf-8",
        }
        try:
            return aliases[codeset]
        except KeyError as exc:
            raise SqliProtocolError(
                f"Unsupported Informix locale codeset {codeset!r}; configure a verified alias"
            ) from exc


    def _decode_text(raw: bytes, encoding: str) -> str:
        """Decode a result string, turning a codeset mismatch into an actionable error.

        Informix converts result data from the database codeset to the client codeset
        on the wire, so ``encoding`` is the CLIENT_LOCALE codec. A strict decode failure
        almost always means CLIENT_LOCALE does not match what the server actually sent
        (for example CLIENT_LOCALE left at en_US.utf8 while the server transmits Latin-1
        for an en_US.819 database). Surface that as a clear diagnostic instead of a bare
        UnicodeDecodeError so the fix -- align CLIENT_LOCALE with the source -- is obvious.
        """

        try:
            return raw.decode(encoding)
        except UnicodeDecodeError as exc:
            raise SqliProtocolError(
                f"Could not decode an Informix result string as {encoding!r}; this usually "
                "means CLIENT_LOCALE does not match the codeset the server is sending "
                "(align CLIENT_LOCALE with the source database's DB_LOCALE)"
            ) from exc


    class SqliUnsupportedAuthentication(SqliProtocolError):
        pass


    class SqliRedirect(SqliUnsupportedAuthentication):
        def __init__(self, detail: str) -> None:
            super().__init__("Informix requested a connection redirect")
            self.detail = detail


    class SqliDescriptorNotImplemented(SqliProtocolError):
        pass


    class _DeadlineReader:
        """Apply one absolute login deadline to every underlying stream read."""

        def __init__(
            self, stream: BinaryIO, connection: socket.socket, deadline: float, maximum: float
        ) -> None:
            self._stream = stream
            self._connection = connection
            self._deadline: float | None = deadline
            self._maximum = maximum

        def read(self, size: int = -1) -> bytes:
            if self._deadline is not None:
                remaining = self._deadline - time.monotonic()
                if remaining <= 0:
                    raise SqliUnsupportedAuthentication("Informix login deadline exceeded")
                self._connection.settimeout(min(self._maximum, remaining))
            return self._stream.read(size)

        def finish(self) -> None:
            self._deadline = None
            self._connection.settimeout(self._maximum)

        def close(self) -> None:
            self._stream.close()


    # Backward-compatible precise name used by callers from the first pure port.
    SqliAuthenticationNotImplemented = SqliUnsupportedAuthentication


    class ConnectionState(Enum):
        NEW = auto()
        SOCKET_OPEN = auto()
        ASC_SENT = auto()
        ACCEPTED = auto()
        AUTHENTICATED = auto()
        DATABASE_OPEN = auto()
        POISONED = auto()
        CLOSED = auto()


